INSERT OR IGNORE INTO ar_ling_root_lemma_furuq_set_src (id, set_id, source_id, chunk_id, source_role, note_md, confidence) VALUES ('NSS:NS:TO:TO_ACCEPT:contrast', 'NS:TO:TO_ACCEPT', 'kmaps_synth', 'contrast', 'contrast', 'قَبِلَ takes in what comes, willingly; تَقَبَّلَ accepts a deed and rewards it; أَخَذَ is taking hold; تَلَقَّى is receiving it to act on; اسْتَجَابَ is answering a call. — Ibn Fāris p.11; al-Rāghib pp. 653, 67, 210; Lane pp. 2983, 3012; al-Zamakhsharī on 2:37 and 9:104', 'high');
